edits.before:
document.getElementById('more').addEventListener('click', event => {
  for (const name of ['Steel trowel', 'Pointing trowel']) { const li = document.createElement('li'); li.textContent = name; document.getElementById('list').append(li); }
  document.getElementById('count').textContent = '4 of 4 results';
  event.currentTarget.remove();
});

edits.after:
document.getElementById('more').addEventListener('click', event => {
  for (const name of ['Steel trowel', 'Pointing trowel']) { const li = document.createElement('li'); li.textContent = name; document.getElementById('list').append(li); }
  document.getElementById('count').textContent = '4 of 4 results';
  document.getElementById('close').focus();
  event.currentTarget.remove();
});
